create database customer_shopping_trend;

show databases;

select * from customer limit 10;

-- Q1. What is the total revenue generated by male vs. female customers?
select gender, sum(purchase_amount) as revenue
from customer
group by gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount? 
select customer_id, purchase_amount
from customer
where discount_applied= 'Yes' and purchase_amount >= (
select avg(purchase_amount)
from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased,round(avg(review_rating),2) as Avg_review_rating
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select shipping_type, round(avg(purchase_amount),2)
from customer
where shipping_type='Standard' or shipping_type='Express'
group by shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
select subscription_status, avg(purchase_amount), sum(purchase_amount)
from customer
group by subscription_status;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased, round(100 * sum(case when discount_applied='Yes' then 1 else 0 end)/count(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.


-- Q8. What are the top 3 most purchased products within each category? 
with my_first_cte as (
select category, item_purchased, count(customer_id) as number_of_sales
from customer
group by category,item_purchased
order by count(customer_id)
limit 3
)
select *
from my_first_cte;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,count(customer_id)
from customer
where previous_purchases>5
group by subscription_status;

-- Q10. What is the revenue contribution of each age group?
select age_group,sum(purchase_amount) as revenue
from customer
group by age_group;


-- Part 1: Subquery Practice Questions

-- Find all customers (customer_id, category, purchase_amount) whose purchase amount is strictly greater than the average purchase amount for that specific product's category.
select customer_id, category, purchase_amount
from customer c1
where purchase_amount > (select avg(purchase_amount)
						 from customer c2
                         where c1.category=c2.category
                         );
                         
-- List all purchases (customer_id, item_purchased, category, review_rating) that belong to categories generating more than $50,000 in total revenue.
select customer_id, item_purchased, category, review_rating
from customer c1
where 50000 < (select sum(purchase_amount)
			   from customer c2
			   where c1.category = c2.category);
					   
-- Retrieve the season, customer_id, item_purchased, and purchase_amount for the single highest purchase amount recorded in each season.
select season, customer_id, item_purchased, purchase_amount
from customer c1
where purchase_amount = (select max(purchase_amount)
						 from customer c2
                         where c1.season=c2.season
                         );
                         
-- Find all customers classified as 'New' (previous_purchases = 1) whose purchase_amount is higher than the average purchase_amount of 'Loyal' customers (previous_purchases > 10).
select customer_id, item_purchased, purchase_amount
from customer 
where previous_purchases=10 and purchase_amount > (select avg(purchase_amount)
												   from customer 
                                                   where previous_purchases>10);

-- Identify each item_purchased whose average review_rating is lower than the overall average review_rating across the entire customer table.
select item_purchased, review_rating
from customer
where review_rating < (select avg(review_rating)
					   from customer);

